import itertools

n = 20
groups = [list(range(4*i, 4*i+4)) for i in range(5)]

edges = set()
# Within each group, all edges (clique)
for g in groups:
    for i, j in itertools.combinations(g, 2):
        edges.add((i, j) if i < j else (j, i))

# Between adjacent groups (i and i+1 mod 5), all edges
for i in range(5):
    g1 = groups[i]
    g2 = groups[(i+1) % 5]
    for v1 in g1:
        for v2 in g2:
            edges.add((v1, v2) if v1 < v2 else (v2, v1))

edge_list = sorted(edges)

# More thorough connectivity check - check ALL subsets of size 3
connectivity_ok = True
bad_sets = []
for S in itertools.combinations(range(n), 3):
    S_set = set(S)
    remaining = [v for v in range(n) if v not in S_set]
    if not remaining:
        continue
    visited = set([remaining[0]])
    queue = [remaining[0]]
    while queue:
        v = queue.pop(0)
        for u in remaining:
            if u not in visited:
                if (v,u) in edge_list or (u,v) in edge_list:
                    visited.add(u)
                    queue.append(u)
    if len(visited) != len(remaining):
        connectivity_ok = False
        bad_sets.append(S)
        if len(bad_sets) <= 5:
            print(f"Connectivity fails for S={S}: visited {len(visited)}/{len(remaining)}")

print(f"Total bad sets: {len(bad_sets)}")
print(f"Vertex connectivity >= 4: {connectivity_ok}")

# Also check vertex connectivity exactly
# Find minimum vertex cut
min_cut = n
for r in range(1, n):
    found_cut = False
    for S in itertools.combinations(range(n), r):
        S_set = set(S)
        remaining = [v for v in range(n) if v not in S_set]
        if len(remaining) < 2:
            continue
        visited = set([remaining[0]])
        queue = [remaining[0]]
        while queue:
            v = queue.pop(0)
            for u in remaining:
                if u not in visited:
                    if (v,u) in edge_list or (u,v) in edge_list:
                        visited.add(u)
                        queue.append(u)
        if len(visited) != len(remaining):
            min_cut = r
            found_cut = True
            print(f"Found vertex cut of size {r}: {S}")
            break
    if found_cut:
        break
print(f"Vertex connectivity: {min_cut}")

